def define_key_terms():
    terms = {
        media_bias: A tendency to present information in a way that reflects a particular perspective or agenda.,
        sensationalism: The use of exciting or shocking stories at the expense of accuracy to provoke public interest.,
        polarization: The division of opinions into two distinct opposing groups.,
        objective_bias: Bias that is based on factual evidence and objective criteria.,
        subjective_bias: Bias that is based on personal opinions, interpretations, or beliefs.
    }
    return terms

