// It aims to highlight the importance of diversity, inclusion, and equality.

function promoteInclusion() {
    const community = {
        values: ['diversity', 'equality', 'respect'],
        actions: []
    };

    community.actions.push('educate', 'listen', 'support');

    console.log('Our community values:');
    community.values.forEach(value => console.log(`- ${value}`));

    console.log('Actions to promote inclusion:');
    community.actions.forEach(action => console.log(`- ${action}`));
}

