// This code snippet represents a simple implementation of a fear response in a character for a game or simulation.
// The character will exhibit a fear response when encountering a specific trigger or threat.

class Character {
    constructor(name) {
        this.name = name;
        this.isAfraid = false;
    }

    encounterThreat(threat) {
        if (this.detectThreat(threat)) {
            this.fearResponse();
        }
    }

    detectThreat(threat) {
        // Logic to determine if the threat is significant enough to cause fear
        // For simplicity, let's assume any non-null threat causes fear
        return threat !== null;
    }

    fearResponse() {
        this.isAfraid = true;
        console.log(`${this.name} is afraid!`);
        // Additional fear response logic can be added here, such as running away or hiding
    }
}

// Example usage:
const character = new Character(Alex);
character.encounterThreat(Spider);

